/* WordBunny Island 1.0 — standalone app, not an extension of another project. */
(async function () {
  'use strict';
  const C=window.BunnyCore,A=window.BunnyArt,E=C.escapeHTML,I=A.icon;
  const APP='wordbunny-island',DB_NAME='wordbunny-island-v1';
  const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const clone=v=>JSON.parse(JSON.stringify(v));
  const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID().slice(0,8):Math.random().toString(36).slice(2,10);
  const stamp=()=>C.dayKey();
  let db=null,persistent=true,state=C.initialState(),custom=[],base=window.BUNNY_STARTER||[],catalogManifest=null;
  let route='home',category='all',wordFilter='all',query='',arcadeCategory='all',game=null,lastSummary=null;
  let toastTimer,gateUntil=0,modalReturn=null,editor=null,importDraft=null,saveQueue=Promise.resolve(),audio=null,melodyTimer=null,musicStep=0,installPrompt=null;
  const outfits=[{id:'scarf',name:'포근한 스카프',price:0},{id:'flower',name:'봄꽃 머리핀',price:30},{id:'bow',name:'딸기 리본',price:60},{id:'hat',name:'숲속 탐험 모자',price:90},{id:'cape',name:'별빛 망토',price:120},{id:'crown',name:'반짝 왕관',price:180}];
  const companions=[{id:'rabbit',name:'버니',xp:0,role:'언제나 함께하는 친구'},{id:'bird',name:'포포',xp:80,role:'노래하는 작은 새'},{id:'fox',name:'루루',xp:200,role:'호기심 가득한 여우'},{id:'panda',name:'모모',xp:400,role:'느긋한 숲속 친구'},{id:'turtle',name:'또또',xp:650,role:'꾸준함의 달인'},{id:'lion',name:'레오',xp:1000,role:'용기를 주는 친구'}];
  const modes=[
    {id:'picture',name:'그림 탐정',desc:'그림 속 주인공은 누구일까? 알맞은 영어 단어를 찾아봐.',icon:'image',tag:'그림 → 영어',bg:'#f4eaf3',ink:'#c49cb9'},
    {id:'listen',name:'소리 숲',desc:'쫑긋! 단어 소리를 듣고 꼭 맞는 카드를 골라봐.',icon:'sound',tag:'듣기 → 고르기',bg:'#e8f2ef',ink:'#91b6a7'},
    {id:'spell',name:'철자 공방',desc:'흩어진 알파벳을 하나씩 모아서 단어를 완성해 봐.',icon:'key',tag:'알파벳 조립',bg:'#eee8f8',ink:'#af95ca'},
    {id:'memory',name:'짝꿍 카드',desc:'카드를 뒤집어 그림과 영어 단어의 짝을 기억해 봐.',icon:'book',tag:'기억력 + 단어',bg:'#edf0fb',ink:'#9ca8ce'},
    {id:'balloon',name:'둥실 풍선',desc:'뜻에 맞는 단어 풍선을 톡! 천천히 골라도 괜찮아.',icon:'bolt',tag:'움직이는 단어',bg:'#fff0e8',ink:'#d2aa88'},
    {id:'ox',name:'맞아? 아닐까?',desc:'그림과 단어가 서로 맞는지 O와 X로 대답해 봐.',icon:'check',tag:'O / X 퀴즈',bg:'#eef3e9',ink:'#a5bd96'},
    {id:'meaning',name:'뜻 찾기',desc:'영어 단어가 어떤 뜻인지, 하나씩 알아보자.',icon:'search',tag:'영어 → 한글',bg:'#f9edef',ink:'#c9a1b1'},
    {id:'type',name:'혼자 써보기',desc:'도움 없이 직접 써보기! 띄어쓰기와 철자를 확인해 봐.',icon:'edit',tag:'직접 입력',bg:'#ebf2f9',ink:'#9cb5cf'}
  ];
  function mode(id){return modes.find(m=>m.id===id)||modes[0];}
  function imageSrc(path){return (window.BUNNY_ASSETS&&window.BUNNY_ASSETS[path])||path;}
  function img(w,cls='',alt=''){return w.image?`<img class="${cls}" src="${E(imageSrc(w.image))}" alt="${E(alt)}" loading="lazy" decoding="async">`:`<span class="word-initial" aria-label="사진 없음">${E(w.en?.[0]?.toUpperCase()||'?')}</span>`;}
  function catalog(){const merged=new Map(base.map(w=>[w.id,w]));custom.forEach(w=>merged.set(w.id,w));return [...merged.values()].filter(w=>!state.hidden.includes(w.id));}
  function word(id){return catalog().find(w=>w.id===id);}
  function categories(){return [...new Set(catalog().map(w=>w.category))];}
  function today(){return state.days[stamp()]||{attempts:0,correct:0,words:[],sessions:0,rewarded:false};}
  function dueWords(){return catalog().filter(w=>state.progress[w.id]&&state.progress[w.id].due<=Date.now());}
  function mastered(){return catalog().filter(w=>state.progress[w.id]?.stage>=4).length;}
  function stageLabel(id){const s=state.progress[id]?.stage||0;return `<span class="stage-label ${s>=4?'mastered':''}">${I(s>=4?'check':'leaf',11)}${['새 단어','새싹','자라는 중','꽃이 피어요','기억했어요','오래 기억'][s]}</span>`;}
  function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
  function celebrate(){if(reduced())return;const box=$('#celebration');box.innerHTML='';for(let n=0;n<34;n++){const el=document.createElement('i');el.className='confetti';el.style.setProperty('--x',`${(Math.random()-.5)*650}px`);el.style.setProperty('--y',`${80+Math.random()*410}px`);el.style.setProperty('--r',`${Math.random()*1000}deg`);el.style.setProperty('--c',['#cab3ed','#efc5d4','#cfdfb7','#f3dc9b','#bad5e8'][n%5]);el.style.animationDelay=`${Math.random()*.13}s`;box.append(el);}setTimeout(()=>box.replaceChildren(),1800);}
  function reduced(){return state.settings.reduced||window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
  function motion(){document.body.classList.toggle('reduce-motion',state.settings.reduced);}
  function soundCtx(){try{if(!audio)audio=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume().catch(()=>{});return audio;}catch{return null;}}
  function tone(freq,time=0,duration=.13,gain=.03,type='sine'){const ctx=soundCtx();if(!ctx)return;const osc=ctx.createOscillator(),v=ctx.createGain();osc.type=type;osc.frequency.value=freq;v.gain.setValueAtTime(0,ctx.currentTime+time);v.gain.linearRampToValueAtTime(gain,ctx.currentTime+time+.012);v.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+time+duration);osc.connect(v);v.connect(ctx.destination);osc.start(ctx.currentTime+time);osc.stop(ctx.currentTime+time+duration+.02);}
  function sfx(type){if(!state.settings.sfx)return;if(type==='correct'){[523.25,659.25,783.99].forEach((f,i)=>tone(f,i*.09,.22,.045));}else if(type==='win'){[523,659,784,1046].forEach((f,i)=>tone(f,i*.12,.32,.04));}else if(type==='wrong'){tone(330,0,.22,.025);tone(294,.13,.25,.018);}else tone(660,0,.07,.018);}
  function syncMusic(){clearInterval(melodyTimer);melodyTimer=null;if(!state.settings.music||document.hidden)return;soundCtx();const notes=[523,0,659,0,784,659,587,0,523,659,0,880,784,0,659,587];melodyTimer=setInterval(()=>{if(window.speechSynthesis?.speaking)return;const f=notes[musicStep++%notes.length];if(f)tone(f,0,.48,.012);},450);}
  document.addEventListener('visibilitychange',()=>{if(document.hidden){window.speechSynthesis?.cancel();clearInterval(melodyTimer);}else if(state.settings.music)syncMusic();});
  function speak(w,slow=false){if(!w)return;if(!('speechSynthesis' in window)){toast('이 브라우저에는 음성 읽기 기능이 없어요. 뜻 찾기로 연습해 주세요.');return false;}try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w.en);u.lang='en-US';u.rate=slow?.65:state.settings.rate;const vs=window.speechSynthesis.getVoices();u.voice=vs.find(v=>v.lang==='en-US'&&v.localService)||vs.find(v=>v.lang?.startsWith('en'))||null;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('영어 음성을 재생하지 못했어요. 기기 음성 설정을 확인하거나 뜻 찾기로 바꿔 주세요.');};window.speechSynthesis.speak(u);return true;}catch{toast('기기의 영어 음성을 사용할 수 없어요.');return false;}}
  async function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('IndexedDB unavailable'));const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>req.result.createObjectStore('kv');req.onsuccess=()=>{req.result.onversionchange=()=>req.result.close();resolve(req.result);};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(new Error('데이터 저장소가 다른 창에서 사용 중이에요.'));});}
  async function readDB(key){if(!db)return null;return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readonly'),q=tx.objectStore('kv').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
  function writeDB(entries){if(!db)return Promise.resolve();return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');for(const [key,value] of Object.entries(entries))tx.objectStore('kv').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('저장이 중단됐어요.'));});}
  function save(includeCustom=false){const snapshot={state:clone(state)};if(includeCustom)snapshot.custom=clone(custom);saveQueue=saveQueue.catch(()=>{}).then(()=>writeDB(snapshot));return saveQueue;}
  async function safeChange(fn){const prev=clone(state),prevCustom=custom.slice(),prevRef=custom,prevLength=custom.length;try{fn();if(custom.length>C.STORED_WORD_LIMIT)throw new Error('직접 저장하는 단어는 최대 10,000개예요. 먼저 내보내기 후 정리해 주세요.');await save(custom!==prevRef||custom.length!==prevLength);}catch(e){state=prev;custom=prevCustom;throw new Error('저장하지 못했어요. 저장 공간을 확인하고 백업해 주세요. '+e.message);}}
  const navs=[['home','home','모험 홈'],['words','book','내 단어장'],['games','game','놀이 광장'],['friends','friends','버니와 친구들'],['records','chart','성장 기록']];
  function navHtml(active){return navs.map(([r,icon,label])=>`<button class="nav-item ${active===r?'active':''}" data-action="nav" data-route="${r}" ${active===r?'aria-current="page"':''}>${I(icon)}<span>${label}</span>${r==='words'?`<small class="nav-badge">${catalog().length}</small>`:''}</button>`).join('');}
  function shell(html,active=route){motion();const playing=['play','study','result'].includes(route);const navActive=playing?'games':active;$('#app').innerHTML=`${!persistent?'<div class="storage-banner" role="alert">이 브라우저에서는 영구 저장을 사용할 수 없어요. 종료 전에 꼭 백업해 주세요.</div>':''}<aside class="sidebar"><button class="brand" data-action="nav" data-route="home" aria-label="워드버니 홈"><span class="brand-mark">${I('friends',29)}</span><span class="brand-copy"><strong>WordBunny</strong><small>I S L A N D</small></span></button><nav class="nav-list" aria-label="메인 메뉴">${navHtml(navActive)}</nav><div class="sidebar-note"><span class="note-icon">${I('image',21)}</span><strong>내 단어가, 나의 모험이 돼요</strong><p>직접 넣은 단어와 사진으로<br>세상에 하나뿐인 단어장.</p><button class="text-btn" data-action="add-word">단어 추가하기 ${I('arrow',14)}</button></div><div class="sidebar-footer">SMALL WORDS, BIG ADVENTURES.</div></aside><div class="main-shell"><header class="topbar"><div class="crumb">나의 작은 영어 세상 <span>/</span> <strong>${E(navs.find(n=>n[0]===navActive)?.[2]||'오늘의 모험')}</strong></div><button class="top-brand-mobile" data-action="nav" data-route="home"><span class="brand-mark">${I('friends',23)}</span><span>WordBunny<small>ISLAND</small></span></button><div class="top-tools"><span class="pill streak" title="연속 학습일">${I('fire')} ${C.streak(state.days)}일</span><span class="pill coins" title="별코인">${I('coin')} <span data-coin-total>${state.coins.toLocaleString()}</span></span><button class="icon-btn" data-action="toggle-sound" aria-label="효과음 ${state.settings.sfx?'끄기':'켜기'}" title="효과음 ${state.settings.sfx?'끄기':'켜기'}">${I(state.settings.sfx?'sound':'mute',20)}</button><button class="icon-btn" data-action="settings" aria-label="설정">${I('settings',20)}</button><span class="profile-dot" aria-hidden="true">${I('friends',24)}</span></div></header><main id="main" class="main-content ${playing?'playing':''}" tabindex="-1">${html}</main></div>${!playing?`<nav class="mobile-nav" aria-label="하단 메뉴">${navHtml(navActive)}</nav>`:''}`;
    $$('img[data-asset]').forEach(el=>el.src=imageSrc(el.dataset.asset));
  }
  function header(eye,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${I('star',11)} ${eye}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
  function home(){const w=catalog(),t=today(),due=dueWords().length,cat=categories();const xpNext=(Math.floor(state.xp/100)+1)*100;const date=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'long'}).format(new Date());
    shell(`${header('A LITTLE ADVENTURE, EVERY DAY',`안녕, ${E(state.name)}!`,'오늘도 버니와 작은 발견을 시작해 볼까?',`<span class="date-label">${date}</span>`)}<div class="dashboard-grid"><div class="dashboard-primary"><section class="hero-card"><div class="hero-copy"><span class="hero-tag">${I('leaf',12)} 나만의 단어로 떠나는 모험</span><h2>작은 단어가<br><em>커다란 모험으로!</em></h2><p>보고, 듣고, 놀다 보면<br>어느새 영어가 내 친구가 돼요.</p><button class="btn btn-primary" data-action="start-adventure">오늘의 모험 시작 ${I('arrow',17)}</button></div>${A.landscape(state.equipped)}</section><div class="stats-strip"><div class="mini-stat"><span class="stat-icon">${I('target',21)}</span><div class="stat-text">오늘의 발견<strong>${t.words.length} <small>단어</small></strong></div></div><div class="mini-stat"><span class="stat-icon">${I('leaf',21)}</span><div class="stat-text">기억한 단어<strong>${mastered()} <small>/ ${w.length}</small></strong></div></div><div class="mini-stat"><span class="stat-icon">${I('fire',21)}</span><div class="stat-text">함께한 날<strong>${C.streak(state.days)} <small>일 연속</small></strong></div></div></div><div class="section-title"><h2>어디로 떠나 볼까? <span class="count">${cat.length}개의 단어 섬</span></h2><button class="text-btn" data-action="nav" data-route="words">전체 보기 ${I('arrow',13)}</button></div><div class="pack-grid">${cat.slice(0,4).map((c,i)=>{const list=w.filter(x=>x.category===c),learned=list.filter(x=>state.progress[x.id]?.stage>=4).length;return `<button class="pack-card" data-action="open-pack" data-category="${E(c)}"><div class="pack-art" style="--pack-bg:${['#fff0dc','#e4f1e7','#eee7f9','#e7f0fb'][i%4]}"><span class="pack-number">ISLAND 0${i+1}</span>${img(list[0])}</div><div class="pack-info"><h3>${E(c)}</h3><p>${list.length}개의 작은 발견 · ${learned}개 기억</p><div class="mini-track"><i style="width:${list.length?learned/list.length*100:0}%"></i></div></div></button>`;}).join('')||'<p>내 단어를 추가하면 첫 번째 단어 섬이 생겨요.</p>'}</div><div class="section-title"><h2>놀면서, 한 번 더!</h2><button class="text-btn" data-action="nav" data-route="games">놀이 광장 ${I('arrow',13)}</button></div><div class="quick-games">${['picture','memory','balloon'].map(id=>{const m=mode(id);return `<button class="quick-game" data-action="choose-game" data-mode="${id}"><span class="game-emblem">${I(m.icon,21)}</span><span><strong>${m.name}</strong><small>${m.tag}</small></span></button>`;}).join('')}</div></div><aside class="dashboard-aside"><section class="panel buddy-panel"><div class="panel-head"><h2>나의 모험 친구</h2><span class="panel-label">MY BUDDY</span></div><div class="buddy-visual">${A.bunny(state.equipped,'buddy')}<span class="buddy-speech">오늘도 반가워!</span></div><div class="buddy-name">버니 <small>Lv. ${1+Math.floor(state.xp/100)}</small></div><p>함께 배우며 조금씩 자라는 중</p><div class="xp-track"><i style="width:${state.xp%100}%"></i></div><div class="xp-caption"><span>다음 레벨까지 ${xpNext-state.xp} XP</span><span>${state.xp} XP</span></div><button class="btn btn-secondary btn-small btn-wide" data-action="nav" data-route="friends">버니 꾸미러 가기 ${I('arrow',13)}</button></section><section class="panel"><div class="panel-head"><h2>오늘의 작은 약속</h2>${I('flag',16)}</div><div class="daily-ring" style="--progress:${Math.min(100,t.correct/state.goal*100)}%"><div><strong>${t.correct}<span>/${state.goal}</span></strong><p>정답 모으기</p></div></div><p class="goal-note">${t.rewarded?'오늘의 약속을 지켰어요. 멋져요!':`약속을 지키면 <strong>별코인 +20</strong>`}</p></section><section class="panel review-panel"><h3>${I('refresh',17)} 다시 만나고 싶은 단어</h3><p>${due?`${due}개의 단어가 기다려요.<br>짧게 복습하며 기억을 키워요.`:'아직 기다리는 단어가 없어요.<br>새 단어와 먼저 인사해 볼까요?'}</p><button class="btn btn-small btn-wide" data-action="start-review">${due?'기억의 숲으로':'새 단어 만나기'} ${I('arrow',13)}</button></section></aside></div><p class="footer-note">빨리 가는 것보다, 즐겁게 한 걸음. 버니가 언제나 응원해요.</p>`);
  }
  function filteredWords(){return catalog().filter(w=>(category==='all'||w.category===category)&&(!query||(w.en+' '+w.ko+' '+w.category).toLowerCase().includes(query.toLowerCase()))&&(wordFilter==='all'||(wordFilter==='custom'&&custom.some(c=>c.id===w.id))||(wordFilter==='favorite'&&state.favorite.includes(w.id))||(wordFilter==='due'&&state.progress[w.id]&&state.progress[w.id].due<=Date.now())));}
  function wordCards(){const list=filteredWords();return list.length?`<div class="word-grid">${list.map(w=>`<article class="word-card" data-word-id="${E(w.id)}">${custom.some(c=>c.id===w.id)?'<span class="origin-tag">내가 넣은 단어</span>':''}<button class="word-img-button" data-action="word-detail" data-id="${E(w.id)}" aria-label="${E(w.en)} 단어 보기"><div class="word-image">${img(w,'',w.en)}</div></button><div class="word-info"><h3>${E(w.en)}</h3><div class="meaning">${E(w.ko)}</div><div class="word-card-tools">${stageLabel(w.id)}<div class="tiny-actions"><button data-action="favorite" data-id="${E(w.id)}" class="${state.favorite.includes(w.id)?'active':''}" aria-label="${E(w.en)} 즐겨찾기" aria-pressed="${state.favorite.includes(w.id)}">${I('heart',15)}</button><button data-action="speak" data-id="${E(w.id)}" aria-label="${E(w.en)} 발음 듣기">${I('sound',17)}</button><button data-action="edit-word" data-id="${E(w.id)}" aria-label="${E(w.en)} 수정">${I('edit',15)}</button></div></div></div></article>`).join('')}</div><p class="footer-note">${list.length}개 단어 · 사진과 단어는 카드 하나에서 모든 놀이로 연결돼요.</p>`:`<section class="empty-state">${I('book',43)}<h2>아직 만나지 못한 단어예요</h2><p>검색어나 주제를 바꿔 보거나, 직접 단어와 사진을 넣어 주세요.</p><button class="btn btn-primary" data-action="add-word">첫 단어 추가하기 ${I('plus',16)}</button></section>`;}
  function wordsPage(){shell(`${header('MY WORD COLLECTION','내 단어, 내 사진, 내 모험','좋아하는 것부터 차근차근. 이 단어들이 모든 놀이에 등장해요.',`<button class="btn btn-primary" data-action="add-word">${I('plus',17)} 단어 추가</button>`)}<div class="content-callout">${I('github',25)}<div><strong>GPT로 단어장을 키우고 싶다면?</strong><br>JSON 단어팩과 사진 폴더를 따로 관리해요.</div><button class="btn btn-outline btn-small" data-action="content-help">관리 방법</button></div><div class="toolbar"><div class="search-box">${I('search',18)}<input id="word-search" type="search" aria-label="단어 검색" placeholder="영어, 뜻, 주제로 찾기" value="${E(query)}"></div><select id="word-category" class="filter-select" aria-label="주제 선택"><option value="all">모든 단어 섬</option>${categories().map(c=>`<option ${category===c?'selected':''} value="${E(c)}">${E(c)}</option>`).join('')}</select><button class="btn btn-outline" data-action="bulk-import">${I('upload',16)} 여러 개 넣기</button></div><div class="chip-row">${[['all','모든 단어'],['custom','직접 넣은 단어'],['favorite','좋아하는 단어'],['due','복습할 단어']].map(([id,label])=>`<button class="chip ${wordFilter===id?'active':''}" data-action="filter" data-filter="${id}">${label}</button>`).join('')}${category!=='all'?`<button class="chip" data-action="start-pack" data-category="${E(category)}">${I('flag',12)} 이 단어 섬에서 놀기</button>`:''}</div><div id="word-results">${wordCards()}</div>`);}
  function gameArt(m){if(['spell','type'].includes(m.id))return '<span class="mini-tile">A</span><span class="mini-tile">B</span>';if(m.id==='memory')return `<span class="mini-tile">${I('image',31)}</span><span class="mini-tile">a</span>`;if(m.id==='ox')return '<span class="mini-tile">O</span><span class="mini-tile">X</span>';return I(m.icon,65).replace('class="icon"','class="icon big-icon"');}
  function gamesPage(){shell(`${header('PLAY, DISCOVER, REMEMBER','어떤 놀이로 만날까?','단어는 같아도, 발견하는 방법은 여덟 가지!')}<div class="arcade-banner"><div class="banner-icon">${I('game',42)}</div><div><h2>내 단어가 모두 게임이 돼요</h2><p>사진을 넣으면 그림 놀이에, 단어를 넣으면 소리와 철자 놀이에.</p></div><select id="arcade-category" class="filter-select" aria-label="게임 단어 주제"><option value="all">모든 단어로 놀기</option>${categories().map(c=>`<option value="${E(c)}" ${arcadeCategory===c?'selected':''}>${E(c)}</option>`).join('')}</select></div><div class="games-grid">${modes.map(m=>`<button class="game-card" data-action="choose-game" data-mode="${m.id}"><div class="game-card-art art-${m.id==='memory'?'matching':m.id}" style="--game-bg:${m.bg};--game-ink:${m.ink}">${gameArt(m)}</div><h2>${m.name}</h2><p>${m.desc}</p><div class="game-card-footer"><span class="mode-label">${m.tag}</span>${I('arrow',19)}</div></button>`).join('')}</div><p class="footer-note">틀려도 하트는 사라지지 않아요. 다시 도전하면 돼요!</p>`);}
  function friendsPage(){shell(`${header('GROW A LITTLE, GLOW A LITTLE','버니와 함께 자라는 중','배운 만큼 반짝! 별코인으로 버니를 꾸미고, 새로운 친구도 만나 봐.')}<div class="friends-layout"><section class="room-card"><div class="room-floor"></div><div class="room-name"><div class="eyebrow">MY LITTLE BUNNY</div><h2>우리 버니</h2><p>Lv. ${1+Math.floor(state.xp/100)} · ${state.xp.toLocaleString()} XP</p><p style="margin-top:14px">${I('coin',14)} 별코인 ${state.coins.toLocaleString()}</p></div>${A.bunny(state.equipped,'room')}</section><div><div class="section-title" style="margin-top:0"><h2>버니의 작은 옷장</h2><span class="panel-label">${state.owned.length} / ${outfits.length} COLLECTED</span></div><div class="closet-grid">${outfits.map(o=>`<article class="outfit-card ${state.equipped===o.id?'equipped':''}"><div class="outfit-preview">${A.bunny(o.id,o.id)}</div><h3>${o.name}</h3><button class="btn ${state.equipped===o.id?'btn-secondary':'btn-outline'}" data-action="outfit" data-id="${o.id}" ${state.equipped===o.id?'disabled':''}>${state.equipped===o.id?`${I('check',12)} 입고 있어요`:state.owned.includes(o.id)?'갈아입기':`${I('coin',12)} ${o.price} · 데려오기`}</button></article>`).join('')}</div><div class="section-title"><h2>숲속 친구 도감</h2><span class="panel-label">${companions.filter(c=>state.xp>=c.xp).length} / ${companions.length} FRIENDS</span></div><div class="companion-grid">${companions.map(c=>`<article class="companion-card ${state.xp<c.xp?'locked':''}"><img src="${imageSrc('content/images/'+c.id+'.svg')}" alt="${c.name}"><h3>${state.xp>=c.xp?c.name:'아직 잠든 친구'}</h3><p>${state.xp>=c.xp?c.role:`${c.xp} XP에서 만나요`}</p>${state.xp>=c.xp?`<span class="unlocked-tag">${I('heart',10)} 우리 이제 친구!</span>`:`<span class="unlocked-tag">${I('lock',10)} ${Math.max(0,c.xp-state.xp)} XP 남았어요</span>`}</article>`).join('')}</div></div></div>`);}
  function recordsPage(){const all=catalog(),ps=all.map(w=>state.progress[w.id]).filter(Boolean),attempts=ps.reduce((a,p)=>a+p.attempts,0),correct=ps.reduce((a,p)=>a+p.correct,0);const seven=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const key=C.dayKey(d);return {key,label:['일','월','화','수','목','금','토'][d.getDay()],count:state.days[key]?.correct||0};});const mx=Math.max(5,...seven.map(d=>d.count));const groups=[{name:'새 단어',n:all.filter(w=>!state.progress[w.id]||state.progress[w.id].stage===0).length},{name:'새싹',n:all.filter(w=>state.progress[w.id]?.stage===1).length},{name:'성장 중',n:all.filter(w=>[2,3].includes(state.progress[w.id]?.stage)).length},{name:'기억함',n:mastered()}];
    shell(`${header('EVERY LITTLE STEP COUNTS','어제보다 한 걸음 더','잘한 날도, 다시 도전한 날도 모두 소중한 성장 기록이에요.')}<div class="report-stats">${[['book',ps.length,'만나 본 단어'],['leaf',mastered(),'오래 기억한 단어'],['target',attempts?Math.round(correct/attempts*100)+'%':'—','도움 없이 맞힌 비율'],['fire',C.streak(state.days)+'일','연속으로 함께한 날']].map(([icon,value,label])=>`<div class="report-stat">${I(icon,24)}<strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="reports-grid"><section class="panel"><div class="panel-head"><h2>이번 주의 발자국</h2><span class="panel-label">LAST 7 DAYS</span></div><div class="weekly-chart" role="img" aria-label="최근 7일 정답 수: ${seven.map(d=>d.label+' '+d.count).join(', ')}">${seven.map(d=>`<div class="chart-day ${d.key===stamp()?'today':''}"><strong>${d.count}</strong><div class="chart-bar" style="height:${Math.max(3,d.count/mx*125)}px"></div><span>${d.label}</span></div>`).join('')}</div><p class="chart-legend">단위: 도움 없이 맞힌 문제 수</p></section><section class="panel"><div class="panel-head"><h2>기억이 자라는 모습</h2><span class="panel-label">WORD GARDEN</span></div>${groups.map(g=>`<div class="mastery-row"><span>${g.name}</span><div class="mini-track"><i style="width:${all.length?g.n/all.length*100:0}%"></i></div><strong>${g.n}</strong></div>`).join('')}<p class="help-block">서로 다른 날의 복습으로 기억이 자라요. 같은 날 여러 번 맞혔다고 완전 암기로 처리하지 않아요.</p></section><section class="panel"><div class="panel-head"><h2>한 번 더 만나면 좋을 단어</h2><button class="text-btn" data-action="start-review">복습하기 ${I('arrow',13)}</button></div><div class="review-list">${dueWords().slice(0,5).map(w=>`<div class="review-item">${img(w,'',w.en)}<div><strong>${E(w.en)}</strong><span>${E(w.ko)}</span></div><button class="text-btn" data-action="speak" data-id="${E(w.id)}" aria-label="${E(w.en)} 듣기">${I('sound',17)}</button></div>`).join('')||'<p class="help-block">지금 복습할 단어는 없어요. 새 단어를 만나면 이곳에 기록이 쌓여요.</p>'}</div></section><section class="panel"><h2>보호자에게 드리는 작은 메모</h2><div class="about-lines" style="margin-top:14px">지금까지 <strong>${attempts}문제</strong>에 도전했어요.<br>힌트를 쓰거나 틀린 단어는 다시 만나도록 남겨 둬요.<br>학습 기록과 직접 넣은 사진은 <strong>이 기기의 이 브라우저</strong>에 저장돼요.<br>다른 기기로 옮길 때는 사진 포함 백업을 사용해 주세요.</div></section></div><section class="export-panel"><div><h3>${I('shield',18)} 소중한 발견을 안전하게</h3><p>사진과 학습 기록 백업 · GitHub용 콘텐츠 내보내기 · 학습 리포트</p></div><div class="export-actions"><button class="btn btn-outline btn-small" data-action="backup">${I('download',14)} 전체 백업</button><button class="btn btn-outline btn-small" data-action="restore">${I('upload',14)} 복원</button><button class="btn btn-outline btn-small" data-action="report-csv">기록 CSV</button></div></section>`);
  }
  function render(){if(route==='words')wordsPage();else if(route==='games')gamesPage();else if(route==='friends')friendsPage();else if(route==='records')recordsPage();else if(route==='study'&&game)renderStudy();else if(route==='play'&&game)renderGame();else if(route==='result'&&lastSummary)renderSummary();else{route='home';home();}}
  function setRoute(next){route=next;try{history.replaceState(null,'','#/'+next);}catch{}render();window.scrollTo(0,0);}
  function navigate(next){if(game&&['play','study'].includes(route)){confirmDialog('잠깐 쉬어 갈까?','지금까지 풀었던 문제는 저장돼요. 아직 끝내지 않은 모험은 처음부터 다시 시작해요.',()=>{game=null;window.speechSynthesis?.cancel();setRoute(next);},'쉬어 가기');return;}setRoute(next);}
  function openModal(title,body,wide=false){if(!$('#modal-root').hasChildNodes())modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="닫기">${I('close',20)}</button></header>${body}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>{$('.modal input:not([type=file]),.modal button,.modal')?.focus();},20);}
  function closeModal(){editor=null;importDraft=null;$('#modal-root').replaceChildren();document.body.style.overflow='';if(modalReturn?.isConnected)modalReturn.focus();modalReturn=null;}
  function modalError(msg){let el=$('.modal .form-error');if(!el){el=document.createElement('div');el.className='form-error';el.setAttribute('role','alert');$('.modal')?.append(el);}el.textContent=msg;}
  function confirmDialog(title,message,callback,label='확인'){openModal(title,`<p class="modal-description" style="margin:0">${E(message)}</p><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">취소</button><button class="btn btn-primary" id="confirm-action">${E(label)}</button></div>`);$('#confirm-action').onclick=async()=>{const b=$('#confirm-action');b.disabled=true;try{closeModal();await callback();}catch(e){toast(e.message);}};}
  function parentGate(callback){if(Date.now()<gateUntil){callback();return;}const a=11+Math.floor(Math.random()*9),b=7+Math.floor(Math.random()*9);openModal('보호자와 함께 열어 주세요',`<form id="parent-gate" class="gate"><div class="gate-icon">${I('shield',37)}</div><p>사진과 단어를 관리하는 공간이에요.<br>아래 계산에 답해 주세요. 이 확인은 비밀번호 보안이 아닌 실수 방지용이에요.</p><div class="gate-question">${a} + ${b} = ?</div><input id="gate-answer" type="text" inputmode="numeric" pattern="[0-9]*" autocomplete="off" aria-label="계산 답" required><button class="btn btn-primary" type="submit">보호자 공간 열기 ${I('arrow',15)}</button></form>`);$('#parent-gate').onsubmit=e=>{e.preventDefault();if(Number($('#gate-answer').value)!==a+b){modalError('답을 한 번 더 확인해 주세요.');return;}gateUntil=Date.now()+15*60*1000;closeModal();callback();};}
  function detail(id){const w=word(id);if(!w)return;openModal('단어와 인사하기',`<div class="study-card question-card"><div class="question-image">${img(w,'',w.en)}</div><div class="question-word">${E(w.en)}</div><div class="question-meaning">${E(w.ko)}</div>${w.example?`<p class="question-example">${E(w.example)}</p>`:''}<div style="margin-top:15px">${stageLabel(w.id)}</div></div><div class="word-detail-footer"><button class="btn btn-primary" data-action="speak" data-id="${E(w.id)}">${I('sound',17)} 발음 듣기</button><button class="btn btn-outline" data-action="edit-word" data-id="${E(w.id)}">${I('edit',16)} 수정</button></div>`);}
  function editorModal(id){const existing=id?word(id):null;editor={id:existing?.id||'',image:existing?.image||'',original:existing,token:uid(),loading:false};const w=existing||{en:'',ko:'',category:category==='all'?'내 단어':category,example:'',level:1};openModal(existing?'단어를 다듬어 볼까요?':'새 단어와 사진을 넣어 주세요',`<form id="word-form"><div class="photo-picker"><div class="photo-preview" id="photo-preview">${editor.image?`<img src="${E(imageSrc(editor.image))}" alt="선택한 사진">`:I('image',35)}</div><div class="photo-controls"><strong>이 단어만의 사진</strong><small>JPG · PNG · WebP / 최대 12MB<br>저장하기 좋은 크기로 자동 줄여요.</small><input type="file" id="photo-file" accept="image/jpeg,image/png,image/webp" class="hidden"><button class="btn btn-secondary btn-small" type="button" data-action="pick-photo">${I('image',14)} 사진 고르기</button> <button class="text-btn" type="button" data-action="remove-photo">사진 없애기</button></div></div><div class="form-grid"><label class="form-field"><span>영어 단어 *</span><input name="en" id="word-en" value="${E(w.en)}" placeholder="예: apple" maxlength="70" required autocapitalize="none" spellcheck="false"></label><label class="form-field"><span>한글 뜻 *</span><input name="ko" id="word-ko" value="${E(w.ko)}" placeholder="예: 사과" maxlength="120" required></label><label class="form-field"><span>단어 섬 / 주제</span><input id="word-cat" list="category-options" value="${E(w.category)}" maxlength="36" placeholder="예: 이번 주 학교 단어"><datalist id="category-options">${categories().map(c=>`<option value="${E(c)}"></option>`).join('')}</datalist></label><label class="form-field"><span>난이도 태그</span><select id="word-level"><option value="1" ${w.level===1?'selected':''}>처음 만나요</option><option value="2" ${w.level===2?'selected':''}>조금 익숙해요</option><option value="3" ${w.level===3?'selected':''}>도전해 볼래요</option></select></label><label class="form-field span-2"><span>쉬운 예문 (선택)</span><input id="word-example" value="${E(w.example)}" placeholder="예: I like apples." maxlength="180"></label></div><div class="help-block">${existing&&base.some(x=>x.id===id)?'기본 단어를 수정하면 이 기기에 나만의 수정본이 저장돼요. GitHub의 원본은 바뀌지 않아요.':'입력한 단어와 사진은 이 기기에 저장돼요. GitHub에 공유하려면 콘텐츠 내보내기를 사용해 주세요.'}<br>아이 얼굴·실명·학교 정보가 담긴 사진은 공개 저장소에 올리지 마세요.</div><div class="form-actions">${existing?`<button type="button" class="delete-link" data-action="delete-word" data-id="${E(id)}">${base.some(x=>x.id===id)?'이 기기에서 숨기기':'이 단어 삭제'}</button>`:''}<button class="btn btn-outline" type="button" data-action="close-modal">취소</button><button class="btn btn-primary" id="save-word" type="submit">${I('check',16)} ${existing?'수정 저장':'단어 추가하기'}</button></div></form>`);
    $('#photo-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;const token=editor?.token;if(editor)editor.loading=true;$('#save-word').disabled=true;try{const data=await compressPhoto(f);if(editor?.token!==token)return;editor.image=data;$('#photo-preview').innerHTML=`<img src="${data}" alt="선택한 사진">`;}catch(err){modalError(err.message);}finally{if(editor?.token===token){editor.loading=false;$('#save-word').disabled=false;}}};
    $('#word-form').onsubmit=async e=>{e.preventDefault();if(!editor||editor.loading)return;const btn=$('#save-word');btn.disabled=true;try{const newId=editor.id||'my-'+uid();const n=C.normalizeWord({id:newId,en:$('#word-en').value,ko:$('#word-ko').value,category:$('#word-cat').value,image:editor.image,example:$('#word-example').value,level:Number($('#word-level').value)},newId);const dup=catalog().find(x=>x.id!==newId&&C.normalizeAnswer(x.en)===C.normalizeAnswer(n.en)&&C.normalizeAnswer(x.ko)===C.normalizeAnswer(n.ko));if(dup)throw new Error('같은 단어와 뜻이 이미 있어요. 기존 단어를 수정해 주세요.');await safeChange(()=>{custom=custom.filter(x=>x.id!==n.id);custom.push(n);state.hidden=state.hidden.filter(x=>x!==n.id);});closeModal();category='all';wordFilter='custom';query='';game=null;setRoute('words');toast(persistent?'단어와 사진을 이 기기에 저장했어요.':'단어를 추가했어요. 영구 저장이 꺼져 있으니 꼭 백업해 주세요.');sfx('correct');}catch(err){modalError(err.message);btn.disabled=false;}};
  }
  async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('JPG, PNG, WebP 사진을 골라 주세요. HEIC 사진은 JPG로 변환해 주세요.');if(file.size>12*1024*1024)throw new Error('12MB보다 작은 사진을 골라 주세요.');const url=URL.createObjectURL(file);try{const im=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('사진을 읽지 못했어요. 다른 사진을 골라 주세요.'));i.src=url;});const scale=Math.min(1,960/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.83);if(data.length>2000000)throw new Error('사진이 너무 커요. 더 작은 사진으로 바꿔 주세요.');return data;}finally{URL.revokeObjectURL(url);}}
  function importModal(){importDraft=null;openModal('여러 단어를 한 번에',`<p class="modal-description">엑셀에서 영어·뜻·주제 열을 복사해 붙여넣거나, CSV / JSON 단어팩을 넣어 주세요.</p><div class="drop-area"><strong>파일로 가져오기</strong><p>CSV · TSV · TXT · JSON / 최대 10MB</p><input id="import-file" type="file" accept=".csv,.tsv,.txt,.json" class="hidden"><button class="btn btn-outline btn-small" data-action="pick-import">${I('upload',14)} 파일 고르기</button></div><label class="form-field"><span>직접 붙여넣기</span><textarea id="bulk-text" rows="6" placeholder="apple / 사과\nbanana / 바나나\n\n또는 영어,뜻,주제,예문 형태의 CSV"></textarea></label><div class="help-block">같은 영어 + 같은 뜻은 중복으로 건너뛰어요. 한 번에 최대 1,000단어.<br>사진은 단어를 추가한 뒤 카드의 수정 버튼으로 넣을 수 있어요.</div><div id="import-result"></div><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">취소</button><button class="btn btn-secondary" data-action="preview-import">내용 확인하기</button><button class="btn btn-primary" id="commit-import" data-action="commit-import" disabled>단어 추가</button></div>`,true);$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){modalError('10MB보다 작은 파일을 넣어 주세요.');return;}$('#bulk-text').value=await f.text();previewImport();};$('#bulk-text').oninput=()=>{importDraft=null;$('#commit-import').disabled=true;$('#import-result').innerHTML='';};}
  function previewImport(){try{$('.modal .form-error')?.remove();const parsed=C.parseWords($('#bulk-text').value,'my-'+uid());const existing=catalog();const known=new Set(existing.map(w=>C.normalizeAnswer(w.en)+'|'+C.normalizeAnswer(w.ko)));let skipped=parsed.duplicates;const added=[];for(const w of parsed.words){if(known.has(C.normalizeAnswer(w.en)+'|'+C.normalizeAnswer(w.ko))){skipped++;continue;}if([...base,...custom].some(x=>x.id===w.id))throw new Error(`기존 단어와 ID가 같아요: ${w.id}. ID를 바꾸거나 기존 단어를 수정해 주세요.`);added.push(w);}importDraft=added;$('#import-result').innerHTML=`<div class="help-block"><strong>${added.length}개 추가 예정</strong> · 중복 ${skipped}개 건너뜀</div><div class="import-preview">${added.slice(0,60).map(w=>`<div class="import-row"><strong>${E(w.en)}</strong><span>${E(w.ko)}</span><span>${E(w.category)}</span></div>`).join('')}${added.length>60?`<div class="import-row">그 외 ${added.length-60}개</div>`:''}</div>`;$('#commit-import').disabled=!added.length;}catch(e){importDraft=null;$('#commit-import').disabled=true;modalError(e.message);}}
  async function commitImport(){if(!importDraft?.length)return;const list=clone(importDraft);$('#commit-import').disabled=true;await safeChange(()=>{custom.push(...list);});closeModal();category='all';query='';wordFilter='custom';game=null;setRoute('words');toast(`${list.length}개 단어를 추가했어요.`);sfx('correct');}
  function download(name,data,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
  async function backup(){await safeChange(()=>state.lastBackup=Date.now());download(`wordbunny-backup-${stamp()}.json`,JSON.stringify({app:APP,schemaVersion:1,exportedAt:new Date().toISOString(),state,custom},null,2));toast('사진과 학습 기록이 포함된 백업을 만들었어요. 안전한 곳에 보관해 주세요.');}
  function restoreModal(){openModal('사진과 학습 기록 복원',`<p class="modal-description">워드버니 아일랜드에서 만든 전체 백업 JSON을 선택하세요. 복원하기 전에 현재 자료를 백업하는 것을 권장해요.</p><input type="file" id="restore-file" accept=".json,application/json" aria-label="백업 파일 선택"><div id="restore-preview"></div><div class="help-block">복원은 이 기기의 기존 단어·사진·학습 기록을 선택한 백업 내용으로 교체해요. GitHub 콘텐츠나 다른 앱에는 영향을 주지 않아요.</div>`);$('#restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>150*1024*1024)throw new Error('150MB 이하의 백업 파일을 선택해 주세요.');const parsed=C.parseBackup(await f.text());$('#restore-preview').innerHTML=`<div class="help-block"><strong>${E(parsed.state.name)}</strong>의 백업<br>직접 넣은 단어 ${parsed.custom.length}개 · 학습한 단어 ${Object.keys(parsed.state.progress).length}개</div><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">취소</button><button id="restore-confirm" class="btn btn-primary">현재 자료를 교체하고 복원</button></div>`;$('#restore-confirm').onclick=async()=>{const b=$('#restore-confirm');b.disabled=true;try{await saveQueue.catch(()=>{});await writeDB({state:parsed.state,custom:parsed.custom});state=parsed.state;custom=parsed.custom;game=null;closeModal();syncMusic();setRoute('home');toast('사진과 학습 기록을 복원했어요.');}catch(err){modalError('복원하지 못했어요. 기존 자료는 유지돼요. '+err.message);b.disabled=false;}};}catch(err){modalError(err.message);}};}
  function contentHelp(){openModal('GPT와 함께 단어장을 키우는 방법',`<div class="about-lines"><strong>새 프로젝트 전용 콘텐츠 구조</strong><br><code>content/manifest.json</code> — 단어팩 목록<br><code>content/packs/*.json</code> — 영어·뜻·주제·예문<br><code>content/images/</code> — 단어 사진과 그림<br><code>AGENTS.md</code> — GPT 작업 안내서</div><div class="help-block"><strong>GPT에게 이렇게 요청하세요</strong><br>“이 새 저장소의 AGENTS.md를 읽고, 첨부한 단어와 사진을 새 단어팩으로 추가해 줘. 기존 단어 ID와 학습 기록 연결은 유지하고, 사진 경로와 JSON을 검증해 줘. 다른 저장소는 변경하지 마.”</div><div class="help-block"><strong>앱에서 입력한 내용은 자동으로 GitHub에 올라가지 않아요.</strong><br>아래 ZIP에는 현재 표시되는 단어 전체와 사진, manifest가 들어가요. 학습 기록은 포함되지 않아요. GPT에게 ZIP을 첨부해 기존 파일과 비교·병합하도록 요청하세요.<br><strong>공개 저장소에는 아이 얼굴·실명·학교 사진을 올리지 마세요.</strong></div><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">닫기</button><button class="btn btn-primary" data-action="export-content">${I('download',16)} GitHub 콘텐츠 ZIP</button></div>`,true);}
  function zipStore(entries){const enc=new TextEncoder(),table=Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0;});const crc=bytes=>{let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0;};const locals=[],central=[];let offset=0,size=0;const put16=(v,o,n)=>v.setUint16(o,n,true),put32=(v,o,n)=>v.setUint32(o,n,true);for(const [name,data]of entries){if(name.includes('..')||name.startsWith('/'))throw new Error('안전하지 않은 ZIP 경로');const filename=enc.encode(name),bytes=typeof data==='string'?enc.encode(data):data;const ch=crc(bytes),l=new Uint8Array(30+filename.length),lv=new DataView(l.buffer);put32(lv,0,0x04034b50);put16(lv,4,20);put16(lv,6,0x800);put32(lv,14,ch);put32(lv,18,bytes.length);put32(lv,22,bytes.length);put16(lv,26,filename.length);l.set(filename,30);locals.push(l,bytes);const c=new Uint8Array(46+filename.length),cv=new DataView(c.buffer);put32(cv,0,0x02014b50);put16(cv,4,20);put16(cv,6,20);put16(cv,8,0x800);put32(cv,16,ch);put32(cv,20,bytes.length);put32(cv,24,bytes.length);put16(cv,28,filename.length);put32(cv,42,offset);c.set(filename,46);central.push(c);size+=c.length;offset+=l.length+bytes.length;}const end=new Uint8Array(22),ev=new DataView(end.buffer);put32(ev,0,0x06054b50);put16(ev,8,entries.length);put16(ev,10,entries.length);put32(ev,12,size);put32(ev,16,offset);return new Blob([...locals,...central,end],{type:'application/zip'});}
  async function assetBytes(path){const src=imageSrc(path);if(src.startsWith('data:')){const body=src.slice(src.indexOf(',')+1);return Uint8Array.from(atob(body),c=>c.charCodeAt(0));}const r=await fetch(src,{cache:'no-cache'});if(!r.ok)throw new Error(`사진을 읽지 못했어요: ${path}`);return new Uint8Array(await r.arrayBuffer());}
  async function exportContent(btn){btn.disabled=true;const before=btn.innerHTML;btn.textContent='단어와 사진을 묶는 중';try{const list=clone(catalog()),entries=[],seen=new Set();for(const w of list){if(!w.image)continue;if(w.image.startsWith('data:')){const mime=w.image.match(/^data:image\/(\w+);/)[1];const path=`content/images/custom/${w.id}.${mime==='jpeg'?'jpg':mime}`;entries.push([path,await assetBytes(w.image)]);w.image=path;}else if(!seen.has(w.image)){entries.push([w.image,await assetBytes(w.image)]);seen.add(w.image);}}
      const packs=[];
      for(let i=0;i<list.length;i+=1000){const id=list.length<=1000?'my-library':'my-library-'+(Math.floor(i/1000)+1);const title=list.length<=1000?'나의 전체 단어장':'나의 단어장 '+(Math.floor(i/1000)+1);const file='content/packs/'+id+'.json';packs.push({id,title,file});entries.push([file,JSON.stringify({schemaVersion:1,id,title,words:list.slice(i,i+1000)},null,2)]);}
      entries.push(['content/manifest.json',JSON.stringify({schemaVersion:1,version:'export-'+stamp(),packs},null,2)],['CONTENT_UPDATE_README.md',`# 워드버니 콘텐츠 내보내기\n이 ZIP은 현재 앱의 ${list.length}개 단어와 사진 전체 스냅샷입니다. 학습 기록, 이름, 별코인은 포함하지 않습니다.\n기존 저장소에 적용하기 전에 AGENTS.md를 읽고 단어 ID, 삭제/숨김 의도, 사진을 비교해 병합하세요. manifest를 무조건 덮어쓰지 마세요.\n1,000단어보다 많으면 여러 단어팩으로 나눠집니다.\n공개 저장소에는 아이 얼굴, 실명, 학교정보가 포함된 사진을 업로드하지 마세요.\n검증: node scripts/validate-content.cjs\n빌드: python scripts/build.py\n`]);download(`wordbunny-content-${stamp()}.zip`,zipStore(entries));toast(`${list.length}개 단어와 사진을 ZIP으로 묶었어요. 공개 전에 사진을 확인해 주세요.`);}catch(e){toast(e.message);}finally{if(btn.isConnected){btn.disabled=false;btn.innerHTML=before;}}}
  function reportCSV(){const rows=[['영어','뜻','주제','도전 수','정답 수','기억 단계','다음 복습','마지막 학습']];for(const w of catalog()){const p=state.progress[w.id]||C.freshProgress();rows.push([w.en,w.ko,w.category,p.attempts,p.correct,p.stage,p.due?new Date(p.due).toLocaleString('ko-KR'):'',p.lastSeen?new Date(p.lastSeen).toLocaleString('ko-KR'):'']);}download(`wordbunny-report-${stamp()}.csv`,'\uFEFF'+rows.map(r=>r.map(C.csvEscape).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('학습 기록 CSV를 만들었어요.');}
  function settingsModal(){openModal('나에게 맞게, 편안하게',`<form id="settings-form"><div class="form-grid"><label class="form-field"><span>불러 줄 이름</span><input id="setting-name" maxlength="18" value="${E(state.name)}" placeholder="탐험가"></label><label class="form-field"><span>오늘의 작은 약속</span><select id="setting-goal">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>하루 ${n}문제 맞히기</option>`).join('')}</select></label></div>${[['sfx','정답 효과음','맞힐 때마다 작은 응원 소리'],['music','포근한 배경음','앱 안에서만 흐르는 작은 멜로디'],['reduced','움직임 줄이기','반짝임과 캐릭터 애니메이션을 줄여요']].map(([key,label,desc])=>`<div class="settings-section"><div class="settings-row"><div><strong>${label}</strong><small>${desc}</small></div><button type="button" class="toggle ${state.settings[key]?'on':''}" data-setting="${key}" role="switch" aria-checked="${state.settings[key]}" aria-label="${label}"></button></div></div>`).join('')}<div class="settings-section"><label class="form-field"><span>영어 발음 속도</span><select id="setting-rate">${[[.65,'아주 천천히'],[.8,'또박또박'],[1,'보통 속도']].map(([r,t])=>`<option value="${r}" ${state.settings.rate===r?'selected':''}>${t}</option>`).join('')}</select></label><small style="font-size:10px;color:#b198c2">목소리와 음성 제공 여부는 기기의 영어 음성 설정에 따라 달라요.</small></div><div class="form-actions"><button type="button" class="btn btn-outline" data-action="close-modal">닫기</button><button type="submit" class="btn btn-primary">설정 저장</button></div></form><div class="settings-section"><div class="settings-row"><div><strong>단어 · 사진 · 기록 관리</strong><small>자동 업로드 없이 이 기기에서 관리해요.</small></div><button class="text-btn" data-action="manage">보호자 공간 ${I('arrow',14)}</button></div></div>${installPrompt?'<button class="btn btn-secondary btn-wide" data-action="install">홈 화면에 앱 설치</button>':''}<p class="notice">WordBunny Island 1.0.0 · 완전히 독립된 새 앱<br>광고 · 결제 · 계정 가입 · 분석 추적이 없어요. 사진은 브라우저 저장 공간을 지우면 사라질 수 있으니 정기적으로 백업해 주세요.</p>`);$$('[data-setting]').forEach(b=>b.onclick=()=>{b.classList.toggle('on');b.setAttribute('aria-checked',b.classList.contains('on'));});$('#settings-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const data={name:$('#setting-name').value,goal:Number($('#setting-goal').value),rate:Number($('#setting-rate').value),settings:Object.fromEntries($$('[data-setting]').map(b=>[b.dataset.setting,b.classList.contains('on')]))};await safeChange(()=>{state.name=C.clean(data.name||'탐험가',18);state.goal=data.goal;Object.assign(state.settings,data.settings,{rate:data.rate});});closeModal();motion();syncMusic();render();toast('설정을 저장했어요.');}catch(err){modalError(err.message);btn.disabled=false;}};}
  function management(){openModal('보호자 콘텐츠 관리',`<div class="about-lines"><strong>내 단어 ${custom.length}개 · 숨긴 단어 ${state.hidden.length}개</strong><br>이 앱의 브라우저 저장소는 다른 앱과 분리되어 있어요.<br>GitHub 콘텐츠와 기기별 학습 기록은 서로 다른 자료예요.</div><div class="settings-section"><div class="export-actions"><button class="btn btn-secondary btn-small" data-action="backup">전체 백업 (사진 포함)</button><button class="btn btn-outline btn-small" data-action="restore">백업 복원</button><button class="btn btn-outline btn-small" data-action="export-content">GitHub용 ZIP</button></div></div><div class="settings-section"><div class="export-actions"><button class="btn btn-outline btn-small" data-action="bulk-import">CSV / JSON 가져오기</button><button class="btn btn-outline btn-small" data-action="refresh-content">GitHub 콘텐츠 새로고침</button><button class="btn btn-outline btn-small" data-action="unhide" ${!state.hidden.length?'disabled':''}>숨긴 기본 단어 다시 표시</button></div></div><p class="help-block">개별 학습 기록은 다른 기기에 자동 공유되지 않아요. 복원 전에 전체 백업을 먼저 만들어 주세요. 단어팩 ZIP에는 학습 기록을 넣지 않아요.</p><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">닫기</button></div>`,true);}
  async function loadCatalog(manual=false){if(window.BUNNY_PORTABLE||!/^https?:$/.test(location.protocol)){if(manual)toast('직접 열기 버전은 내장 단어를 사용해요. GitHub에 올린 앱에서 새 콘텐츠를 받아요.');return;}
    try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);let manifest,loaded;try{const r=await fetch('content/manifest.json',{cache:'no-cache',signal:controller.signal});if(!r.ok)throw new Error('manifest 응답 '+r.status);manifest=await r.json();if(manifest.schemaVersion!==1||!Array.isArray(manifest.packs)||!manifest.packs.length||manifest.packs.length>80)throw new Error('단어팩 목록 형식 오류');const parts=await Promise.all(manifest.packs.map(async p=>{if(!/^content\/packs\/[a-zA-Z0-9_-]+\.json$/.test(p.file))throw new Error('단어팩 경로 오류');const x=await fetch(p.file,{cache:'no-cache',signal:controller.signal});if(!x.ok)throw new Error(p.file+' 응답 '+x.status);return C.parseWords(await x.text(),p.id).words;}));loaded=parts.flat();if(loaded.length>C.STORED_WORD_LIMIT)throw new Error('GitHub 전체 콘텐츠는 최대 10,000단어까지 지원해요.');const ids=new Set();for(const w of loaded){if(ids.has(w.id))throw new Error('단어 ID 중복: '+w.id);ids.add(w.id);}}finally{clearTimeout(timer);}await writeDB({catalog:loaded,manifest});base=loaded;catalogManifest=manifest;if(!['play','study','result'].includes(route))render();if(manual)toast(`${base.length}개 GitHub 단어를 확인했어요. 직접 입력한 단어와 학습 기록은 유지돼요.`);}catch(e){console.warn('WordBunny content fallback:',e.message);if(manual)toast('새 콘텐츠를 받지 못했어요. 저장된 단어는 그대로 사용할 수 있어요. '+e.message);}}
  // Learning flow. Each answer is saved before progression; same-day repetition cannot inflate mastery.
  function startAdventure(cat='all',review=false){closeModal();const pool=catalog().filter(w=>cat==='all'||w.category===cat);const deck=C.selectDeck(pool,state.progress,5,review);if(!deck.length){if(review){toast('지금 복습할 단어는 없어요. 새 단어를 만나 보세요.');startAdventure(cat,false);}else{toast('먼저 단어를 추가해 주세요.');setRoute('words');}return;}game={kind:'adventure',deck,pool:catalog(),studyIndex:0,queue:[],index:0,current:null,stats:{attempts:0,correct:0,earned:0},errors:new Set(),retried:new Set(),startCoins:state.coins,busy:false};setRoute('study');}
  function renderStudy(){const w=game.deck[game.studyIndex];shell(`<div class="learning-shell"><div class="learning-top"><button class="icon-btn" data-action="leave-game" aria-label="모험 나가기">${I('close',19)}</button><div class="learning-progress"><i style="width:${(game.studyIndex+1)/game.deck.length*100}%"></i></div><span class="learning-counter">만나기 ${game.studyIndex+1}/${game.deck.length}</span></div><div class="learning-label">SAY HELLO TO A NEW WORD</div><h1 class="learning-title">먼저 단어와 인사해 볼까?</h1><p class="learning-sub">사진을 보고, 소리를 듣고, 한 번 따라 말해 봐.</p><div class="study-counter">${game.deck.map((_,i)=>`<i class="${i===game.studyIndex?'active':''}"></i>`).join('')}</div><div class="study-card question-card"><div class="question-image">${img(w,'',w.ko)}</div><div class="question-word">${E(w.en)}</div><div class="question-meaning">${E(w.ko)}</div>${w.example?`<p class="question-example">${E(w.example)}</p>`:''}</div><div class="study-actions"><button class="btn btn-outline" data-action="speak-current">${I('sound',17)} 소리 듣기</button><button class="btn btn-outline" data-action="speak-slow">${I('sound',15)} 천천히</button><button class="btn btn-primary" data-action="study-next">${game.studyIndex===game.deck.length-1?'이제 놀러 가자!':'다음 단어 만나기'} ${I('arrow',17)}</button></div><p class="footer-note">목소리는 녹음하지 않아요. 편하게 따라 읽으면 돼요.</p></div>`);}
  function studyNext(){if(!game)return;if(++game.studyIndex<game.deck.length){renderStudy();return;}game.queue=game.deck.map(w=>({word:w,type:w.image?'picture':'meaning'})).concat(C.shuffle(game.deck).map((w,i)=>({word:w,type:i%2===0?'listen':'spell'})));game.studyIndex=game.deck.length-1;setRoute('play');}
  function chooseGame(id){closeModal();const m=mode(id),cat=arcadeCategory;openModal(m.name,`<p class="modal-description">${m.desc}</p><label class="form-field"><span>어떤 단어로 놀까요?</span><select id="game-category"><option value="all">모든 단어 (${catalog().length}개)</option>${categories().map(c=>`<option value="${E(c)}" ${cat===c?'selected':''}>${E(c)} (${catalog().filter(w=>w.category===c).length}개)</option>`).join('')}<option value="_favorite">즐겨찾기 단어</option></select></label><div class="help-block">${id==='memory'?'최대 네 쌍의 그림·단어 카드를 뒤집으며 짝을 찾아요. 사진 없는 단어는 한글 뜻으로 나와요.':'최대 10문제로 짧게 놀아요. 틀리거나 힌트를 쓴 단어는 한 번 더 등장해요.'}<br>빠르게 누르는 것보다 천천히 생각하는 게 더 중요해요.</div><div class="form-actions"><button class="btn btn-outline" data-action="close-modal">닫기</button><button class="btn btn-primary" id="start-selected-game">놀이 시작 ${I('arrow',16)}</button></div>`);$('#start-selected-game').onclick=()=>{const c=$('#game-category').value;const pool=catalog().filter(w=>c==='all'||(c==='_favorite'?state.favorite.includes(w.id):w.category===c));if(!pool.length){modalError('먼저 이 주제에 단어를 넣어 주세요.');return;}if(['picture','meaning','listen','balloon','ox'].includes(id)&&C.choiceOptions(pool[0],pool,'en').length<2){modalError('서로 다른 영어 단어가 2개 이상 필요해요. 다른 주제를 선택하거나 단어를 더 넣어 주세요.');return;}closeModal();startGame(id,pool);};}
  function startGame(id,pool){const deck=C.selectDeck(pool,state.progress,id==='memory'?4:10,false);game={kind:id,deck,pool,index:0,queue:deck.map(w=>({word:w,type:id})),current:null,stats:{attempts:0,correct:0,earned:0},errors:new Set(),retried:new Set(),startCoins:state.coins,busy:false};if(id==='memory'){game.cards=C.shuffle(deck.flatMap(w=>[{key:w.id+'-image',word:w,face:'image'},{key:w.id+'-word',word:w,face:'word'}]));game.flipped=[];game.matched=new Set();game.missed=new Set();game.turns=0;}setRoute('play');}
  function initQuestion(){if(game.current)return;const q=game.queue[game.index];if(!q)return;const cur={...q,hinted:false,feedback:null,letters:[],selected:[],guess:'',options:null,busy:false};if(cur.type==='picture'&&!cur.word.image)cur.type='meaning';if(cur.type==='listen'&&!('speechSynthesis'in window))cur.type='meaning';if(['picture','meaning','listen','balloon'].includes(cur.type)){cur.options=C.choiceOptions(cur.word,game.pool,cur.type==='meaning'?'ko':'en');if(cur.options.length<2&&game.pool!==catalog())cur.options=C.choiceOptions(cur.word,catalog(),cur.type==='meaning'?'ko':'en');}
    if(cur.type==='spell')cur.letters=C.shuffle([...C.normalizeAnswer(cur.word.en)].map((ch,i)=>({ch,id:i})));
    if(cur.type==='ox'){const wrong=C.shuffle(game.pool.filter(w=>C.normalizeAnswer(w.en)!==C.normalizeAnswer(cur.word.en)))[0];cur.oxCorrect=!wrong||Math.random()>.5;cur.displayWord=cur.oxCorrect?cur.word:wrong;}
    game.current=cur;
  }
  function learningTop(){return `<div class="learning-top"><button class="icon-btn" data-action="leave-game" aria-label="놀이 나가기">${I('close',19)}</button><div class="learning-progress"><i style="width:${game.kind==='memory'?game.matched.size/game.deck.length*100:game.index/game.queue.length*100}%"></i></div><span class="learning-counter">${game.kind==='memory'?`${game.matched.size}/${game.deck.length}쌍`: `${game.index+1}/${game.queue.length}`}</span><span class="pill coins">${I('coin',14)} +${game.stats.earned}</span></div>`;}
  function renderGame(){if(game.kind==='memory'){renderMemory();return;}initQuestion();const q=game.current;if(!q){finishGame();return;}const w=q.word,m=mode(q.type),isAnswered=!!q.feedback;let prompt='',content='',answers='';
    if(q.type==='picture'){prompt='이 그림의 영어 이름은?';content=`<div class="question-image">${img(w,'',w.ko)}</div>`;}
    if(q.type==='meaning'){prompt='어떤 뜻일까?';content=`<div class="question-word">${E(w.en)}</div><p class="listen-hint">영어 단어와 어울리는 뜻을 찾아봐.</p>`;}
    if(q.type==='listen'){prompt='쫑긋! 어떤 단어가 들릴까?';content=`<button class="listen-orb" data-action="speak-current" aria-label="문제 단어 듣기">${I('sound',47)}</button><p class="listen-hint">소리 버튼을 눌러 듣고 골라봐.</p><button class="text-btn" data-action="listen-fallback" style="margin-top:10px">소리가 안 들려요 · 뜻 찾기로 바꾸기</button>`;}
    if(q.type==='spell'||q.type==='type'){prompt=q.type==='spell'?'알파벳을 모아 단어를 만들어 봐!':'혼자서도 쓸 수 있을까?';content=`${w.image?`<div class="question-image">${img(w,'',w.ko)}</div>`:''}<div class="question-meaning" style="margin-top:10px">${E(w.ko)}</div>`;}
    if(q.type==='balloon'){prompt='뜻에 맞는 풍선을 톡!';content=`<div class="question-meaning" style="font-size:35px;margin:12px 0">${E(w.ko)}</div>${w.image?`<div class="question-image" style="width:115px;height:104px">${img(w,'',w.ko)}</div>`:''}`;}
    if(q.type==='ox'){prompt='그림과 영어 단어가 맞을까?';content=`${w.image?`<div class="question-image">${img(w,'',w.ko)}</div>`:`<div class="question-meaning">${E(w.ko)}</div>`}<div class="question-word" style="margin:10px 0 0">${E(q.displayWord.en)}</div>`;}
    if(['picture','meaning','listen'].includes(q.type))answers=`<div class="options-grid">${q.options.map((o,i)=>`<button class="answer-btn ${q.feedback?(o.id===w.id?'correct':o.id===q.guess?'wrong':''):''}" data-action="answer-choice" data-id="${E(o.id)}" ${isAnswered?'disabled':''}><span class="answer-index">${i+1}</span>${q.type==='listen'&&o.image?img(o,'option-thumb',''):''}<span>${E(q.type==='meaning'?o.ko:o.en)}</span>${q.feedback&&o.id===w.id?I('check',20):''}</button>`).join('')}</div>`;
    if(q.type==='spell')answers=`<div class="spell-slots" aria-label="만드는 단어">${[...C.normalizeAnswer(w.en)].map((_,i)=>{const letter=q.selected[i];return `<button class="letter-slot ${letter!==undefined?'filled':''}" data-action="remove-letter" data-index="${i}" aria-label="${i+1}번째 글자 ${letter!==undefined?E(q.letters.find(l=>l.id===letter).ch):'빈칸'}" ${isAnswered?'disabled':''}>${letter!==undefined?E(q.letters.find(l=>l.id===letter).ch===' '?'␣':q.letters.find(l=>l.id===letter).ch):''}</button>`;}).join('')}</div><div class="letter-bank">${q.letters.map(l=>`<button class="letter-btn" data-action="letter" data-index="${l.id}" ${q.selected.includes(l.id)||isAnswered?'disabled':''} aria-label="${l.ch===' '?'띄어쓰기':E(l.ch)}">${l.ch===' '?'␣':E(l.ch)}</button>`).join('')}</div><div class="study-actions"><button class="btn btn-outline" data-action="reset-letters" ${isAnswered?'disabled':''}>다시 놓기</button><button class="btn btn-primary" data-action="submit-spell" ${q.selected.length!==q.letters.length||isAnswered?'disabled':''}>다 만들었어요 ${I('check',17)}</button></div>`;
    if(q.type==='type')answers=`<form id="typing-form" class="typing-area"><input id="typing-answer" type="text" maxlength="100" autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="영어 정답 입력" placeholder="영어로 써 볼까?" value="${E(q.guess)}" ${isAnswered?'disabled':''}><button class="btn btn-primary" type="submit" ${isAnswered?'disabled':''}>확인</button></form>`;
    if(q.type==='ox')answers=`<div class="ox-grid"><button class="ox-btn ${q.guess==='true'?'selected':''}" data-action="answer-ox" data-value="true" aria-label="O, 맞아요" ${isAnswered?'disabled':''}>O</button><button class="ox-btn ${q.guess==='false'?'selected':''}" data-action="answer-ox" data-value="false" aria-label="X, 아니에요" ${isAnswered?'disabled':''}>X</button></div>`;
    if(q.type==='balloon')answers=`<div class="balloon-field">${q.options.map(o=>`<button class="balloon-answer ${q.feedback&&o.id===q.guess?'popped':''}" data-action="answer-choice" data-id="${E(o.id)}" ${isAnswered?'disabled':''}>${E(o.en)}</button>`).join('')}</div>`;
    const feed=q.feedback?`<div class="feedback ${q.feedback.correct&&!q.hinted?'':'incorrect'}" role="status"><div><strong>${q.feedback.correct?(q.hinted?'도움받아 완성했어!':'맞았어! 멋진 발견이야.'): '괜찮아, 이번에 같이 기억하자.'}</strong><p>${E(w.en)} = ${E(w.ko)}${!q.feedback.correct||q.hinted?' · 조금 뒤에 다시 만나자.':''}${q.feedback.bonus?' · 오늘의 약속 달성! 별코인 +20':''}</p></div><button class="btn btn-primary" data-action="next-question">${game.index===game.queue.length-1?'모험 마치기':'다음으로'} ${I('arrow',16)}</button></div>`:'';
    shell(`<div class="learning-shell">${learningTop()}<div class="learning-label">${game.kind==='adventure'?'TODAY’S LITTLE ADVENTURE':m.name}</div><h1 class="learning-title">${prompt}</h1><p class="learning-sub">${q.retry?'한 번 더 만나니까 반갑지? 천천히 다시 해보자.':'틀려도 괜찮아. 버니와 함께 생각해 보자.'}</p><section class="question-card">${!['listen','spell','type','ox'].includes(q.type)?`<button class="icon-btn question-sound" data-action="speak-current" aria-label="단어 발음 듣기">${I('sound',20)}</button>`:''}${content}</section>${q.hinted&&!q.feedback?`<p class="hint-box">${E(w.en)} · ${E(w.ko)} — 힌트 없이 기억할 때까지 다시 만나자.</p>`:''}${answers}${feed}<div class="learning-bottom"><button class="text-btn" data-action="hint" ${isAnswered?'disabled':''}>${I('leaf',13)} 힌트가 필요해</button><span>모르면 배울 기회! 재도전은 한 번 더.</span><button class="text-btn" data-action="skip" ${isAnswered?'disabled':''}>아직 모르겠어 ${I('arrow',13)}</button></div></div>`);
    if(q.type==='type')$('#typing-form').onsubmit=e=>{e.preventDefault();if(!q.feedback){q.guess=$('#typing-answer').value;answer(C.normalizeAnswer(q.guess)===C.normalizeAnswer(w.en));}};
  }
  async function answer(correct,guess){if(!game||game.busy||game.current?.feedback)return;const g=game,q=g.current;g.busy=true;const snap=clone(state);const val=guess??q.guess;q.guess=val;try{const r=C.grade(state,q.word.id,correct,Date.now(),q.hinted);await save();g.stats.attempts++;if(correct&&!q.hinted)g.stats.correct++;g.stats.earned+=r.earned+r.bonus;if(!correct||q.hinted){g.errors.add(q.word.id);if(!g.retried.has(q.word.id)){g.retried.add(q.word.id);g.queue.splice(Math.min(g.queue.length,g.index+3),0,{word:q.word,type:q.type,retry:true});}}q.feedback={correct,bonus:r.bonus};sfx(correct?'correct':'wrong');if(correct&&!q.hinted)celebrate();renderGame();}catch(e){state=snap;toast('정답 기록을 저장하지 못했어요. 다시 시도해 주세요.');}finally{g.busy=false;}}
  function nextQuestion(){if(!game?.current?.feedback||game.busy)return;game.index++;game.current=null;if(game.index>=game.queue.length)finishGame();else{renderGame();window.scrollTo(0,0);}}
  function renderMemory(){const g=game;shell(`<div class="learning-shell">${learningTop()}<div class="learning-label">LITTLE MEMORY GARDEN</div><h1 class="learning-title">숨은 짝꿍을 찾아봐!</h1><p class="learning-sub">사진 카드와 영어 단어 카드는 단짝 친구야.</p><div class="match-grid">${g.cards.map((c,i)=>{const matched=g.matched.has(c.word.id),open=matched||g.flipped.includes(i);return `<button class="match-tile ${matched?'matched':''} ${g.flipped.includes(i)?'selected':''}" data-action="memory-card" data-index="${i}" data-card-key="${E(c.key)}" aria-label="${open?E(c.face==='word'?c.word.en:c.word.ko):'뒤집지 않은 카드 '+(i+1)}" ${matched||g.busy?'disabled':''}>${open?(c.face==='word'?E(c.word.en):(c.word.image?img(c.word,'',c.word.ko):E(c.word.ko))):I('friends',36)}</button>`;}).join('')}</div><div class="matching-hud"><span>${I('heart',15)} ${g.matched.size}쌍 발견</span><span>${I('refresh',15)} ${g.turns}번 뒤집기</span></div><p class="footer-note">처음에 못 찾아도 괜찮아. 위치를 기억했다가 한 번 더!</p></div>`);}
  async function memoryCard(index){const g=game;if(!g||g.kind!=='memory'||g.busy||g.flipped.includes(index)||g.matched.has(g.cards[index]?.word.id))return;g.flipped.push(index);sfx('tap');if(g.flipped.length<2){renderMemory();return;}g.busy=true;g.turns++;const [a,b]=g.flipped.map(i=>g.cards[i]);renderMemory();if(a.word.id===b.word.id&&a.face!==b.face){const snap=clone(state);try{const r=C.grade(state,a.word.id,true,Date.now(),g.missed.has(a.word.id));await save();g.stats.attempts++;if(!g.missed.has(a.word.id))g.stats.correct++;g.stats.earned+=r.earned+r.bonus;g.matched.add(a.word.id);sfx('correct');celebrate();}catch(e){state=snap;toast('기록을 저장하지 못했어요. 다시 짝을 찾아 주세요.');}await new Promise(r=>setTimeout(r,420));}else{g.missed.add(a.word.id);g.missed.add(b.word.id);g.errors.add(a.word.id);g.errors.add(b.word.id);sfx('wrong');await new Promise(r=>setTimeout(r,820));}if(game!==g)return;g.flipped=[];g.busy=false;if(g.matched.size===g.deck.length)finishGame();else renderMemory();}
  async function finishGame(){const g=game;if(!g||g.finishing)return;g.finishing=true;try{await safeChange(()=>{const t=state.days[stamp()]||(state.days[stamp()]={attempts:0,correct:0,words:[],sessions:0,rewarded:false});t.sessions++;});lastSummary={kind:g.kind,deck:g.deck,stats:g.stats,errors:[...g.errors],earned:g.stats.earned};game=null;sfx('win');setRoute('result');celebrate();}catch(e){g.finishing=false;toast('모험 마무리를 저장하지 못했어요. 다시 눌러 주세요.');}}
  function renderSummary(){const s=lastSummary,perfect=s.stats.attempts&&s.stats.correct===s.stats.attempts;shell(`<section class="summary"><div class="summary-mascot">${A.bunny(state.equipped,'summary')}</div><div class="summary-stars">${I('star')}${I('star')}${I('star')}</div><h1>${perfect?'반짝반짝, 멋진 모험이었어!':'오늘도 한 뼘 자랐어!'}</h1><p>맞힌 단어도, 다시 만날 단어도 모두 너의 소중한 발견이야.</p><div class="summary-stats"><div class="summary-stat"><strong>${s.deck.length}</strong><span>만난 단어</span></div><div class="summary-stat"><strong>${s.stats.correct}/${s.stats.attempts}</strong><span>${s.kind==='memory'?'도움 없이 찾은 짝':'도움 없이 맞힌 문제'}</span></div><div class="summary-stat"><strong>+${s.earned}</strong><span>모은 별코인</span></div></div><div class="summary-words">${s.deck.map(w=>`<button class="summary-word ${s.errors.includes(w.id)?'needs-work':''}" data-action="word-detail" data-id="${E(w.id)}">${I(s.errors.includes(w.id)?'refresh':'check',12)} ${E(w.en)}</button>`).join('')}</div><p class="help-block">${s.errors.length?`${s.errors.length}개 단어는 다시 만나면서 더 친해질 거야. 틀린 기록은 복습 목록에 남겨 두었어.`:'오늘 만난 단어는 날짜를 두고 다시 복습해요. 기억이 오래오래 자라도록!'}${s.kind==='memory'?'<br>카드의 짝을 잘못 골랐던 단어는 정답 보상 대신 복습으로 남겨요.':''}</p><div class="summary-buttons"><button class="btn btn-outline" data-action="nav" data-route="home">모험 홈으로</button><button class="btn btn-primary" data-action="nav" data-route="friends">버니 만나기 ${I('arrow',16)}</button></div></section>`);}
  // Central event routing: all imported/user strings are escaped before rendering.
  document.addEventListener('click',async ev=>{const b=ev.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{
    if(a==='nav'){closeModal();navigate(b.dataset.route);}
    else if(a==='close-modal')closeModal();
    else if(a==='settings')settingsModal();
    else if(a==='toggle-sound'){await safeChange(()=>state.settings.sfx=!state.settings.sfx);sfx('tap');render();}
    else if(a==='speak')speak(word(id));
    else if(a==='word-detail')detail(id);
    else if(a==='favorite'){await safeChange(()=>{state.favorite=state.favorite.includes(id)?state.favorite.filter(x=>x!==id):[...state.favorite,id];});if(route==='words')$('#word-results').innerHTML=wordCards();}
    else if(a==='add-word')parentGate(()=>editorModal());
    else if(a==='edit-word')parentGate(()=>editorModal(id));
    else if(a==='pick-photo')$('#photo-file').click();
    else if(a==='remove-photo'){if(editor){editor.image='';$('#photo-preview').innerHTML=I('image',35);}}
    else if(a==='delete-word'){const baseWord=base.some(w=>w.id===id);confirmDialog(baseWord?'기본 단어를 숨길까요?':'이 단어를 삭제할까요?',baseWord?'이 기기에서만 숨겨요. 보호자 공간에서 다시 표시할 수 있어요.':'직접 넣은 단어와 사진을 이 기기에서 삭제해요. 백업이 없다면 복구할 수 없어요.',async()=>{await safeChange(()=>{custom=custom.filter(w=>w.id!==id);if(baseWord)state.hidden=[...new Set([...state.hidden,id])];state.favorite=state.favorite.filter(x=>x!==id);});game=null;setRoute('words');toast(baseWord?'단어를 숨겼어요.':'단어를 삭제했어요.');},baseWord?'숨기기':'삭제하기');}
    else if(a==='filter'){wordFilter=b.dataset.filter;wordsPage();}
    else if(a==='open-pack'){category=b.dataset.category;wordFilter='all';query='';setRoute('words');}
    else if(a==='start-pack')startAdventure(b.dataset.category);
    else if(a==='bulk-import')parentGate(importModal);
    else if(a==='pick-import')$('#import-file').click();
    else if(a==='preview-import')previewImport();
    else if(a==='commit-import')await commitImport();
    else if(a==='content-help')contentHelp();
    else if(a==='backup')parentGate(()=>backup().catch(e=>toast(e.message)));
    else if(a==='restore')parentGate(restoreModal);
    else if(a==='export-content')parentGate(()=>exportContent(b.isConnected?b:document.createElement('button')));
    else if(a==='report-csv')parentGate(reportCSV);
    else if(a==='manage')parentGate(management);
    else if(a==='refresh-content'){await loadCatalog(true);}
    else if(a==='unhide'){await safeChange(()=>state.hidden=[]);closeModal();render();toast('숨겼던 기본 단어를 다시 표시했어요.');}
    else if(a==='outfit'){const o=outfits.find(x=>x.id===id);if(!o)return;if(state.owned.includes(id)){await safeChange(()=>state.equipped=id);friendsPage();sfx('correct');}else if(state.coins<o.price)toast(`별코인이 ${o.price-state.coins}개 더 필요해요. 함께 단어를 배워 볼까?`);else confirmDialog(o.name+' 데려오기',`별코인 ${o.price}개로 구매해요. 구매 후 남는 별코인: ${state.coins-o.price}개`,async()=>{await safeChange(()=>{if(state.coins<o.price||state.owned.includes(id))throw new Error('이미 구매했거나 코인이 부족해요.');state.coins-=o.price;state.owned.push(id);state.equipped=id;});friendsPage();celebrate();sfx('win');},'구매하고 입히기');}
    else if(a==='start-adventure')startAdventure();
    else if(a==='start-review')startAdventure('all',true);
    else if(a==='choose-game')chooseGame(b.dataset.mode);
    else if(a==='leave-game')navigate('games');
    else if(a==='speak-current')speak(route==='study'?game?.deck[game.studyIndex]:game?.current?.word);
    else if(a==='speak-slow')speak(game?.deck[game.studyIndex],true);
    else if(a==='study-next')studyNext();
    else if(a==='answer-choice')await answer(id===game?.current?.word.id,id);
    else if(a==='answer-ox')await answer((b.dataset.value==='true')===game?.current?.oxCorrect,b.dataset.value);
    else if(a==='next-question')nextQuestion();
    else if(a==='letter'){const q=game?.current;if(q&&!q.feedback&&!q.selected.includes(Number(b.dataset.index))&&q.selected.length<q.letters.length){q.selected.push(Number(b.dataset.index));sfx('tap');renderGame();}}
    else if(a==='remove-letter'){const q=game?.current;if(q&&!q.feedback){q.selected.splice(Number(b.dataset.index),1);renderGame();}}
    else if(a==='reset-letters'){if(game?.current&&!game.current.feedback){game.current.selected=[];renderGame();}}
    else if(a==='submit-spell'){const q=game?.current;if(q){q.guess=q.selected.map(i=>q.letters.find(l=>l.id===i).ch).join('');await answer(C.normalizeAnswer(q.guess)===C.normalizeAnswer(q.word.en));}}
    else if(a==='hint'){if(game?.current&&!game.current.feedback){game.current.hinted=true;renderGame();speak(game.current.word);}}
    else if(a==='skip')await answer(false,'_skip');
    else if(a==='listen-fallback'){const q=game?.current;if(q&&!q.feedback){q.type='meaning';q.options=C.choiceOptions(q.word,game.pool,'ko');renderGame();}}
    else if(a==='memory-card')await memoryCard(Number(b.dataset.index));
    else if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;closeModal();}}
  }catch(err){console.error('WordBunny action error:',err);if($('.modal'))modalError(err.message);else toast(err.message||'잠시 문제가 생겼어요. 다시 시도해 주세요.');}});
  document.addEventListener('input',e=>{if(e.target.id==='word-search'){query=e.target.value;$('#word-results').innerHTML=wordCards();}});
  document.addEventListener('change',e=>{if(e.target.id==='word-category'){category=e.target.value;wordsPage();}if(e.target.id==='arcade-category')arcadeCategory=e.target.value;});
  document.addEventListener('error',e=>{const el=e.target;if(el instanceof HTMLImageElement&&!el.dataset.fallback){el.dataset.fallback='true';el.removeAttribute('src');el.alt='사진을 불러오지 못했어요';el.style.fontSize='12px';el.style.color='#aa8bbd';}},true);
  document.addEventListener('keydown',e=>{const modal=$('.modal');if(modal){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const nodes=[...modal.querySelectorAll('button:not(:disabled),input:not([type=file]),select,textarea,a[href],[tabindex="0"]')].filter(n=>n.offsetParent!==null);if(!nodes.length){e.preventDefault();modal.focus();return;}const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}
    if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;
    if(route==='play'&&game?.current){const q=game.current;if(q.feedback&&e.key==='Enter'){e.preventDefault();nextQuestion();}else if(!q.feedback&&q.options&&/^[1-4]$/.test(e.key)){const o=q.options[Number(e.key)-1];if(o){e.preventDefault();answer(o.id===q.word.id,o.id);}}}
  });
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
  window.addEventListener('hashchange',()=>{const r=location.hash.replace('#/','');if(navs.some(n=>n[0]===r)){if(game)game=null;route=r;render();}});
  window.addEventListener('unhandledrejection',e=>{console.error('WordBunny async failure:',e.reason);toast('작업을 완료하지 못했어요. 데이터는 삭제하지 않았어요.');});
  try{db=await openDB();const saved=await readDB('state'),savedCustom=await readDB('custom'),savedBase=await readDB('catalog');if(saved)state=C.validateState(saved);if(Array.isArray(savedCustom)&&savedCustom.length)custom=C.parseWords(JSON.stringify(savedCustom),'saved',C.STORED_WORD_LIMIT).words;if(Array.isArray(savedBase)&&savedBase.length)base=C.parseWords(JSON.stringify(savedBase),'saved-base',C.STORED_WORD_LIMIT).words;}catch(e){console.warn('Storage unavailable:',e);persistent=false;db=null;}
  route=location.hash.replace('#/','')||'home';render();loadCatalog(false);
  if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)&&!window.BUNNY_PORTABLE){navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Offline worker:',e.message));}
})();
